              "text": "Tim had a little task. A big tin bin sat by a mat. A thin stick sat in the bin. Tim picked the stick up and put it by a small bag. A quick little pig ran past the bag in a zigzag. Tim had to grin. The pig did not sit still. It sniffed the mat, tipped the bin, and ran up a hill. Tim fixed the bin and put the stick back in it. Then Tim sat for a bit. A little chick came near. It picked at a bit of food and hid by the bin. Tim did not grab it. Tim sat still and let the chick come close. A soft wind hit the hill. Tim put a lid on the bin so the bits in it did not spill. Then Tim had a quick snack. A cat sat on the mat and blinked. The cat did not hiss. It sat still as the pig, chick, and Tim rested. At last, Tim packed the bag, checked the lid, and picked up the stick. The task was finished. Tim felt glad. It had been a busy but fun visit. Tim sat still for a bit. The pig sniffed, the chick picked, and the cat blinked. The bin and lid stayed fixed. Tim sat still for a bit. The pig sniffed, the chick picked, and the cat blinked. The bin and lid stayed fixed. Tim sat still for a bit. The pig sniffed, the chick picked, and the cat blinked. The bin and lid stayed fixed."
