              "targetWordHits": 40,
              "text": "Tom had a hot job to do. A pot sat by a cat. Tom had to top and get the job done. A map sat close by and did not move. Tom put a mop by the pot. Then Tom saw a hop near a bag. It was a small thing, but Tom did not rush. Tom had a plan. First, Tom set the mop in a safe spot. Next, Tom got the log. A little cap came past and had a quick look. It did not grab the log. Tom gave it a pat and went back to the job. The hop moved a bit, then stopped. Tom had to top once more. Soon the job was set. The hot part was done, but Tom still had one more task. A dog was by the path. Tom had to put it next to the fog. The path was not long. Tom went step by step and did not quit. At the end, Tom sat down for a short rest. The map came back and sat near Tom. Tom looked at the mop, the log, the dog, and the fog. All of it was in the right spot. Tom felt glad. It had been a busy job, but the plan had worked. Tom had one last look. The hot was still there. The pot did not tip. The mop did not slip. Tom had done a good job. A small hop sat near the cat. Tom did not mind. It stayed still for a bit, then moved off."
